let windowRecordingStates = new Map, sidepanelConnected = !1, sidepanelCheckInterval = (chrome.runtime.onInstalled.addListener(() => { chrome.sidePanel.setPanelBehavior({ openPanelOnActionClick: !0 }) }), null);

// IndexedDB 存储模块引用
let db = null, DB_NAME = 'SnapScribeDB', DB_VERSION = 1, STORE_NAME = 'recordings';

// ========== 稳定性优化 ==========
// 最大步骤数限制，防止数据过大
const MAX_STEPS = 100;
// 最大存储大小警告阈值 (字节)
const STORAGE_WARN_SIZE = 50 * 1024 * 1024; // 50MB
// 重试次数
const MAX_RETRIES = 3;

// 存储使用情况监控
let storageInfo = { stepCount: 0, totalSize: 0 };

// 数据校验：确保步骤数据完整
function validateStep(step) {
    if (!step) return false;
    if (typeof step.title !== 'string') return false;
    if (typeof step.screenshot !== 'string') return false;
    if (!step.screenshot.startsWith('data:image/')) return false;
    return true;
}

// 数据清理：移除无效步骤
function cleanSteps(steps) {
    if (!Array.isArray(steps)) return [];
    return steps.filter(step => validateStep(step)).slice(0, MAX_STEPS);
}

// 计算数据大小
function calculateDataSize(steps) {
    let size = 0;
    steps.forEach(step => {
        if (step.screenshot) size += step.screenshot.length * 0.75;
        if (step.title) size += step.title.length * 2;
    });
    return Math.round(size);
}

// 获取存储使用情况
function getStorageUsage() {
    return storageInfo;
}

// Service Worker 保活心跳
let keepAliveInterval = null;
function startKeepAlive() {
    if (keepAliveInterval) return;
    keepAliveInterval = setInterval(() => {
        console.log('[KeepAlive] Service Worker is alive');
    }, 25000); // 每25秒一次
}
startKeepAlive();

// IndexedDB 初始化
async function initDB() {
    if (db) return db;
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onerror = () => {
            console.error('[IndexedDB] 打开数据库失败:', request.error);
            reject(request.error);
        };
        request.onsuccess = () => { 
            db = request.result; 
            console.log('[IndexedDB] 数据库初始化成功');
            resolve(db); 
        };
        request.onupgradeneeded = (event) => {
            const database = event.target.result;
            if (!database.objectStoreNames.contains(STORE_NAME)) {
                database.createObjectStore(STORE_NAME, { keyPath: 'id' });
            }
        };
    });
}

// 带重试的 IndexedDB 保存
async function saveToIndexedDB(data, retries = 0) {
    try {
        await initDB();
        
        // 数据校验和清理
        const cleanedSteps = cleanSteps(data.steps || []);
        const dataSize = calculateDataSize(cleanedSteps);
        
        // 更新存储信息
        storageInfo = { stepCount: cleanedSteps.length, totalSize: dataSize };
        
        // 大小警告
        if (dataSize > STORAGE_WARN_SIZE) {
            console.warn('[Storage] 数据大小超过警告阈值:', (dataSize/1024/1024).toFixed(2), 'MB');
        }
        
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_NAME], 'readwrite');
            const store = transaction.objectStore(STORE_NAME);
            const record = {
                id: 'lastRecording',
                steps: cleanedSteps,
                savedAt: Date.now(),
                version: 1 // 数据版本，用于迁移
            };
            
            transaction.oncomplete = () => {
                console.log('[IndexedDB] 保存成功，步骤数:', cleanedSteps.length, '大小:', (dataSize/1024).toFixed(1), 'KB');
                resolve(true);
            };
            transaction.onerror = () => {
                console.error('[IndexedDB] 保存失败:', transaction.error);
                reject(transaction.error);
            };
            
            store.put(record);
        });
    } catch (e) {
        console.error('[IndexedDB] 保存异常:', e);
        if (retries < MAX_RETRIES) {
            console.log('[IndexedDB] 重试中...', retries + 1, '/', MAX_RETRIES);
            await new Promise(r => setTimeout(r, 500));
            return saveToIndexedDB(data, retries + 1);
        }
        return false;
    }
}

// IndexedDB 加载录制数据
async function loadFromIndexedDB(retries = 0) {
    try {
        await initDB();
        return new Promise((resolve) => {
            const transaction = db.transaction([STORE_NAME], 'readonly');
            const store = transaction.objectStore(STORE_NAME);
            const request = store.get('lastRecording');
            
            request.onsuccess = () => {
                const result = request.result;
                if (result && result.steps) {
                    // 数据版本迁移检查
                    if (result.version !== 1) {
                        console.log('[IndexedDB] 检测到数据版本变化，执行迁移...');
                    }
                    // 自动清理无效数据
                    const cleanedSteps = cleanSteps(result.steps);
                    if (cleanedSteps.length !== result.steps.length) {
                        console.log('[IndexedDB] 清理了', result.steps.length - cleanedSteps.length, '个无效步骤');
                    }
                    console.log('[IndexedDB] 加载成功，步骤数:', cleanedSteps.length);
                    storageInfo = { stepCount: cleanedSteps.length, totalSize: calculateDataSize(cleanedSteps) };
                    resolve({ steps: cleanedSteps, savedAt: result.savedAt });
                } else {
                    resolve(null);
                }
            };
            request.onerror = () => {
                console.error('[IndexedDB] 加载失败');
                resolve(null);
            };
        });
    } catch (e) {
        console.error('[IndexedDB] 加载异常:', e);
        if (retries < MAX_RETRIES) {
            await new Promise(r => setTimeout(r, 500));
            return loadFromIndexedDB(retries + 1);
        }
        return null;
    }
}

// IndexedDB 清除数据
async function clearIndexedDB() {
    try {
        await initDB();
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        store.delete('lastRecording');
        storageInfo = { stepCount: 0, totalSize: 0 };
        console.log('[IndexedDB] 数据已清除');
        return true;
    } catch (e) {
        console.error('[IndexedDB] 清除失败:', e);
        return false;
    }
}

// 更新插件图标角标显示截图数量
function updateBadge(windowId) {
    console.log('[Badge] updateBadge called with windowId:', windowId);
    let state = windowRecordingStates.get(windowId);
    console.log('[Badge] state:', state);
    if (state && state.currentTabId) {
        console.log('[Badge] setting badge for tabId:', state.currentTabId);
        let count = state.steps ? state.steps.length : 0;
        if (count > 0) {
            let text = count > 99 ? '99+' : count.toString();
            chrome.action.setBadgeText({ text: text, tabId: state.currentTabId }).then(() => console.log('[Badge] badge set to:', text)).catch(e => console.error('[Badge] error:', e));
            chrome.action.setBadgeBackgroundColor({ color: '#ff4444', tabId: state.currentTabId }).catch(() => {});
        } else {
            chrome.action.setBadgeText({ text: '\u25CF', tabId: state.currentTabId }).then(() => console.log('[Badge] badge set to: recording')).catch(e => console.error('[Badge] error:', e));
            chrome.action.setBadgeBackgroundColor({ color: '#44ff44', tabId: state.currentTabId }).catch(() => {});
        }
    } else {
        console.log('[Badge] no state or currentTabId for windowId:', windowId);
    }
}

// 清除角标
function clearBadge(windowId) {
    let state = windowRecordingStates.get(windowId);
    if (state && state.currentTabId) {
        chrome.action.setBadgeText({ text: '', tabId: state.currentTabId }).catch(() => {});
    }
}

// 保存录制数据到 IndexedDB
let lastRecordingData = null;

// Service worker 启动时从 IndexedDB 加载之前保存的数据
async function loadStartupData() {
    const savedData = await loadFromIndexedDB();
    if (savedData) {
        lastRecordingData = savedData;
        console.log('[Data] Restored recording data on startup, steps:', lastRecordingData && lastRecordingData.steps ? lastRecordingData.steps.length : 0);
    }
}
loadStartupData();

// 异步保存录制数据到 IndexedDB
async function saveRecordingSteps(windowId) {
    let state = windowRecordingStates.get(windowId);
    if (state && state.steps) {
        lastRecordingData = { steps: state.steps, savedAt: Date.now() };
        await saveToIndexedDB(lastRecordingData);
    }
}

// 停止录制时强制同步到 IndexedDB
async function forceSaveRecordingSteps(windowId) {
    let state = windowRecordingStates.get(windowId);
    if (state && state.steps) {
        lastRecordingData = { steps: state.steps, savedAt: Date.now() };
        await saveToIndexedDB(lastRecordingData);
        console.log('[Storage] 强制保存成功，步骤数:', state.steps.length);
    }
}

